const pptxgen = require("pptxgenjs");

const slideConfig = {
  type: 'cover',
  index: 1,
  title: 'The Global Burden of Mental Illness'
};

function createSlide(pres, theme) {
  const slide = pres.addSlide();
  slide.background = { color: theme.primary };

  // Decorative accent bar at top
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0, y: 0, w: 10, h: 0.08,
    fill: { color: theme.accent }
  });

  // Subtle geometric shapes for visual interest
  slide.addShape(pres.shapes.OVAL, {
    x: 7.2, y: 0.8, w: 2.2, h: 2.2,
    fill: { color: theme.secondary, transparency: 70 }
  });
  slide.addShape(pres.shapes.OVAL, {
    x: 8.0, y: 2.5, w: 1.6, h: 1.6,
    fill: { color: theme.accent, transparency: 75 }
  });
  slide.addShape(pres.shapes.OVAL, {
    x: 6.5, y: 3.2, w: 1.0, h: 1.0,
    fill: { color: theme.light, transparency: 70 }
  });

  // Title
  slide.addText("The Global Burden\nof Mental Illness", {
    x: 0.7, y: 1.0, w: 6.5, h: 2.2,
    fontSize: 44, fontFace: "Georgia",
    color: "FFFFFF", bold: true, align: "left",
    lineSpacingMultiple: 1.1
  });

  // Subtitle
  slide.addText("Prevalence, Impact, and the Treatment Gap", {
    x: 0.7, y: 3.3, w: 6.5, h: 0.6,
    fontSize: 22, fontFace: "Calibri",
    color: theme.light, align: "left"
  });

  // Horizontal accent line
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0.7, y: 4.1, w: 1.5, h: 0.04,
    fill: { color: theme.accent }
  });

  // Source attribution
  slide.addText("Data: Our World in Data / IHME, Global Burden of Disease (2025)", {
    x: 0.7, y: 4.4, w: 6, h: 0.4,
    fontSize: 11, fontFace: "Calibri",
    color: theme.secondary, align: "left"
  });

  // Year badge
  slide.addText("2023 Data", {
    x: 0.7, y: 4.85, w: 1.2, h: 0.35,
    fontSize: 12, fontFace: "Calibri",
    color: theme.primary, bold: true,
    align: "center", valign: "middle",
    fill: { color: theme.light },
    rectRadius: 0.15
  });

  return slide;
}

if (require.main === module) {
  const pres = new pptxgen();
  pres.layout = 'LAYOUT_16x9';
  const theme = {
    primary: "006d77",
    secondary: "83c5be",
    accent: "e29578",
    light: "ffddd2",
    bg: "edf6f9"
  };
  createSlide(pres, theme);
  pres.writeFile({ fileName: "slide-01-preview.pptx" });
}

module.exports = { createSlide, slideConfig };

