const pptxgen = require("pptxgenjs");

const slideConfig = {
  type: 'content',
  index: 5,
  title: 'Schizophrenia and Bipolar: Lower Prevalence but Severe Impact'
};

function createSlide(pres, theme) {
  const slide = pres.addSlide();
  slide.background = { color: theme.bg };

  // Title
  slide.addText("Schizophrenia and Bipolar Disorder", {
    x: 0.5, y: 0.25, w: 9, h: 0.55,
    fontSize: 30, fontFace: "Georgia",
    color: theme.primary, bold: true, align: "left",
    margin: 0
  });
  slide.addText("Lower Prevalence but Severe Individual Impact", {
    x: 0.5, y: 0.8, w: 9, h: 0.35,
    fontSize: 16, fontFace: "Calibri",
    color: theme.accent, align: "left",
    margin: 0
  });

  // Full comparison bar chart - all 5 categories
  const chartData = [{
    name: "DALYs per 100,000",
    labels: ["Eating disorders", "Bipolar disorder", "Schizophrenia", "Anxiety disorders", "Depressive disorders"],
    values: [47.5, 94.6, 210.2, 686.5, 694.6]
  }];

  slide.addChart(pres.charts.BAR, chartData, {
    x: 0.4, y: 1.3, w: 5.5, h: 3.2,
    barDir: "bar",
    chartColors: [theme.secondary],
    showValue: true,
    dataLabelPosition: "outEnd",
    dataLabelColor: theme.primary,
    dataLabelFontSize: 10,
    dataLabelFontFace: "Calibri",
    catAxisLabelColor: theme.primary,
    catAxisLabelFontSize: 11,
    catAxisLabelFontFace: "Calibri",
    valAxisLabelColor: theme.secondary,
    valGridLine: { color: theme.light, size: 0.5 },
    catGridLine: { style: "none" },
    showLegend: false,
    showTitle: false,
    chartArea: { fill: { color: "FFFFFF" }, roundedCorners: true },
    plotArea: { fill: { color: "FFFFFF" } },
    valAxisMinVal: 0,
    valAxisMaxVal: 800
  });

  // Right side - Focus cards for Schizophrenia and Bipolar
  // Schizophrenia card
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 6.2, y: 1.3, w: 3.5, h: 1.5,
    fill: { color: "FFFFFF" },
    shadow: { type: "outer", blur: 6, offset: 2, angle: 135, color: "000000", opacity: 0.1 },
    rectRadius: 0.1
  });
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 6.2, y: 1.3, w: 3.5, h: 0.06,
    fill: { color: theme.accent },
    rectRadius: 0
  });

  slide.addText("210.2", {
    x: 6.2, y: 1.5, w: 3.5, h: 0.7,
    fontSize: 40, fontFace: "Georgia",
    color: theme.accent, bold: true, align: "center", valign: "middle"
  });
  slide.addText("Schizophrenia — DALYs per 100K", {
    x: 6.2, y: 2.2, w: 3.5, h: 0.3,
    fontSize: 12, fontFace: "Calibri",
    color: theme.primary, bold: true, align: "center"
  });
  slide.addText("High individual disability despite\nlower population prevalence", {
    x: 6.2, y: 2.5, w: 3.5, h: 0.5,
    fontSize: 10, fontFace: "Calibri",
    color: theme.secondary, align: "center", lineSpacingMultiple: 1.2
  });

  // Bipolar card
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 6.2, y: 3.0, w: 3.5, h: 1.5,
    fill: { color: "FFFFFF" },
    shadow: { type: "outer", blur: 6, offset: 2, angle: 135, color: "000000", opacity: 0.1 },
    rectRadius: 0.1
  });
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 6.2, y: 3.0, w: 3.5, h: 0.06,
    fill: { color: theme.primary },
    rectRadius: 0
  });

  slide.addText("94.6", {
    x: 6.2, y: 3.2, w: 3.5, h: 0.7,
    fontSize: 40, fontFace: "Georgia",
    color: theme.primary, bold: true, align: "center", valign: "middle"
  });
  slide.addText("Bipolar Disorder — DALYs per 100K", {
    x: 6.2, y: 3.9, w: 3.5, h: 0.3,
    fontSize: 12, fontFace: "Calibri",
    color: theme.primary, bold: true, align: "center"
  });
  slide.addText("Significant individual burden,\nsmaller population-level share", {
    x: 6.2, y: 4.2, w: 3.5, h: 0.5,
    fontSize: 10, fontFace: "Calibri",
    color: theme.secondary, align: "center", lineSpacingMultiple: 1.2
  });

  // Bottom insight bar
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0.5, y: 4.7, w: 9, h: 0.55,
    fill: { color: theme.primary, transparency: 8 },
    rectRadius: 0.08
  });
  slide.addText("While population-level burden is lower, individual severity and disability are high — specialized care remains essential.", {
    x: 0.7, y: 4.7, w: 8.6, h: 0.55,
    fontSize: 12, fontFace: "Calibri",
    color: theme.primary, align: "left", valign: "middle"
  });

  // Source note
  slide.addText("Source: IHME, Global Burden of Disease (2025). World, 2023.", {
    x: 0.5, y: 5.2, w: 6, h: 0.3,
    fontSize: 9, fontFace: "Calibri",
    color: theme.secondary, align: "left"
  });

  // Page number badge
  slide.addShape(pres.shapes.OVAL, {
    x: 9.3, y: 5.1, w: 0.4, h: 0.4,
    fill: { color: theme.accent }
  });
  slide.addText("5", {
    x: 9.3, y: 5.1, w: 0.4, h: 0.4,
    fontSize: 12, fontFace: "Arial",
    color: "FFFFFF", bold: true,
    align: "center", valign: "middle"
  });

  return slide;
}

if (require.main === module) {
  const pres = new pptxgen();
  pres.layout = 'LAYOUT_16x9';
  const theme = {
    primary: "006d77",
    secondary: "83c5be",
    accent: "e29578",
    light: "ffddd2",
    bg: "edf6f9"
  };
  createSlide(pres, theme);
  pres.writeFile({ fileName: "slide-05-preview.pptx" });
}

module.exports = { createSlide, slideConfig };

