const pptxgen = require("pptxgenjs");

const slideConfig = {
  type: 'content',
  index: 6,
  title: 'Treatment Gap'
};

function createSlide(pres, theme) {
  const slide = pres.addSlide();
  slide.background = { color: theme.bg };

  // Title
  slide.addText("Treatment Is Available but Often\nLacking or Poor Quality", {
    x: 0.5, y: 0.25, w: 9, h: 0.8,
    fontSize: 28, fontFace: "Georgia",
    color: theme.primary, bold: true, align: "left",
    margin: 0, fit: "shrink"
  });

  // Four barrier cards in a 2x2 grid
  const cards = [
    { icon: "!", label: "Stigma", desc: "Many people are uncomfortable disclosing symptoms to healthcare professionals or people they know.", color: theme.accent },
    { icon: "+", label: "Access", desc: "Treatment is often lacking, especially in low- and middle-income countries.", color: theme.primary },
    { icon: "~", label: "Quality", desc: "Even where treatment exists, it may be of poor quality.", color: theme.secondary },
    { icon: "?", label: "Underreporting", desc: "Discomfort with disclosure makes it difficult to estimate the true prevalence, meaning the actual burden may be higher than reported.", color: "c9785c" }
  ];

  const cardW = 4.2;
  const cardH = 1.7;
  const startX = 0.5;
  const startY = 1.3;
  const gapX = 0.6;
  const gapY = 0.3;

  cards.forEach((card, i) => {
    const col = i % 2;
    const row = Math.floor(i / 2);
    const cx = startX + col * (cardW + gapX);
    const cy = startY + row * (cardH + gapY);

    // Card background
    slide.addShape(pres.shapes.RECTANGLE, {
      x: cx, y: cy, w: cardW, h: cardH,
      fill: { color: "FFFFFF" },
      shadow: { type: "outer", blur: 6, offset: 2, angle: 135, color: "000000", opacity: 0.1 },
      rectRadius: 0.1
    });

    // Icon circle
    slide.addShape(pres.shapes.OVAL, {
      x: cx + 0.2, y: cy + 0.25, w: 0.6, h: 0.6,
      fill: { color: card.color }
    });

    // Icon text
    slide.addText(card.icon, {
      x: cx + 0.2, y: cy + 0.25, w: 0.6, h: 0.6,
      fontSize: 22, fontFace: "Georgia",
      color: "FFFFFF", bold: true,
      align: "center", valign: "middle"
    });

    // Label
    slide.addText(card.label, {
      x: cx + 1.0, y: cy + 0.2, w: 2.9, h: 0.35,
      fontSize: 18, fontFace: "Georgia",
      color: theme.primary, bold: true, align: "left", valign: "middle"
    });

    // Description
    slide.addText(card.desc, {
      x: cx + 1.0, y: cy + 0.6, w: 2.9, h: 0.9,
      fontSize: 11, fontFace: "Calibri",
      color: theme.secondary, align: "left", valign: "top",
      lineSpacingMultiple: 1.2
    });
  });

  // Bottom insight
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0.5, y: 4.65, w: 9, h: 0.55,
    fill: { color: theme.primary, transparency: 8 },
    rectRadius: 0.08
  });
  slide.addText("Good data is essential to understand these conditions — how, when, and why they occur, and how they can be treated effectively.", {
    x: 0.7, y: 4.65, w: 8.6, h: 0.55,
    fontSize: 12, fontFace: "Calibri",
    color: theme.primary, align: "left", valign: "middle"
  });

  // Page number badge
  slide.addShape(pres.shapes.OVAL, {
    x: 9.3, y: 5.1, w: 0.4, h: 0.4,
    fill: { color: theme.accent }
  });
  slide.addText("6", {
    x: 9.3, y: 5.1, w: 0.4, h: 0.4,
    fontSize: 12, fontFace: "Arial",
    color: "FFFFFF", bold: true,
    align: "center", valign: "middle"
  });

  return slide;
}

if (require.main === module) {
  const pres = new pptxgen();
  pres.layout = 'LAYOUT_16x9';
  const theme = {
    primary: "006d77",
    secondary: "83c5be",
    accent: "e29578",
    light: "ffddd2",
    bg: "edf6f9"
  };
  createSlide(pres, theme);
  pres.writeFile({ fileName: "slide-06-preview.pptx" });
}

module.exports = { createSlide, slideConfig };

