const pptxgen = require("pptxgenjs");

const slideConfig = {
  type: 'content',
  index: 7,
  title: 'How People Cope'
};

function createSlide(pres, theme) {
  const slide = pres.addSlide();
  slide.background = { color: theme.bg };

  // Title
  slide.addText("How People Cope", {
    x: 0.5, y: 0.25, w: 9, h: 0.55,
    fontSize: 32, fontFace: "Georgia",
    color: theme.primary, bold: true, align: "left",
    margin: 0
  });

  // Subtitle
  slide.addText("From Medication to Faith to Family Conversations", {
    x: 0.5, y: 0.8, w: 9, h: 0.35,
    fontSize: 16, fontFace: "Calibri",
    color: theme.accent, align: "left",
    margin: 0
  });

  // Three strategy columns
  const strategies = [
    {
      icon: "Rx",
      label: "Prescribed Medication",
      desc: "Common in higher-income settings where healthcare infrastructure and access to pharmaceuticals are more readily available.",
      color: theme.primary
    },
    {
      icon: "✦",
      label: "Religious & Spiritual Activities",
      desc: "Prevalent in many regions worldwide, reflecting cultural and faith-based approaches to managing mental health.",
      color: theme.accent
    },
    {
      icon: "•••",
      label: "Talking to Friends & Family",
      desc: "A widely reported coping mechanism across countries, highlighting the role of social support in mental health.",
      color: theme.secondary
    }
  ];

  const colW = 2.8;
  const startX = 0.5;
  const gap = 0.45;

  strategies.forEach((s, i) => {
    const cx = startX + i * (colW + gap);

    // Card background
    slide.addShape(pres.shapes.RECTANGLE, {
      x: cx, y: 1.4, w: colW, h: 3.3,
      fill: { color: "FFFFFF" },
      shadow: { type: "outer", blur: 6, offset: 2, angle: 135, color: "000000", opacity: 0.1 },
      rectRadius: 0.1
    });

