      x: cx + (colW - 0.9) / 2, y: 1.6, w: 0.9, h: 0.9,
      fill: { color: s.color }
    });

    // Icon text
    slide.addText(s.icon, {
      x: cx + (colW - 0.9) / 2, y: 1.6, w: 0.9, h: 0.9,
      fontSize: 20, fontFace: "Georgia",
      color: "FFFFFF", bold: true,
      align: "center", valign: "middle"
    });

    // Label
    slide.addText(s.label, {
      x: cx + 0.15, y: 2.65, w: colW - 0.3, h: 0.5,
      fontSize: 14, fontFace: "Calibri",
      color: theme.primary, bold: true, align: "center", valign: "middle"
    });

    // Description
    slide.addText(s.desc, {
      x: cx + 0.2, y: 3.2, w: colW - 0.4, h: 1.3,
      fontSize: 11, fontFace: "Calibri",
      color: theme.secondary, align: "left", valign: "top",
      lineSpacingMultiple: 1.3
    });
  });

  // Bottom insight bar
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0.5, y: 4.85, w: 9, h: 0.55,
    fill: { color: theme.primary, transparency: 8 },
    rectRadius: 0.08
  });
  slide.addText("Coping strategies vary widely across countries and cultures — policy must account for these differences, not apply a one-size-fits-all approach.", {
    x: 0.7, y: 4.85, w: 8.6, h: 0.55,
    fontSize: 12, fontFace: "Calibri",
    color: theme.primary, align: "left", valign: "middle"
  });

  // Page number badge
  slide.addShape(pres.shapes.OVAL, {
    x: 9.3, y: 5.1, w: 0.4, h: 0.4,
    fill: { color: theme.accent }
  });
  slide.addText("7", {
    x: 9.3, y: 5.1, w: 0.4, h: 0.4,
    fontSize: 12, fontFace: "Arial",
    color: "FFFFFF", bold: true,
    align: "center", valign: "middle"
  });

  return slide;
}

if (require.main === module) {
  const pres = new pptxgen();
  pres.layout = 'LAYOUT_16x9';
  const theme = {
    primary: "006d77",
    secondary: "83c5be",
