const pptxgen = require("pptxgenjs");

const slideConfig = {
  type: 'summary',
  index: 8,
  title: 'Key Takeaways'
};

function createSlide(pres, theme) {
  const slide = pres.addSlide();
  slide.background = { color: theme.primary };

  // Subtle decorative shapes
  slide.addShape(pres.shapes.OVAL, {
    x: 8.2, y: -0.3, w: 2.5, h: 2.5,
    fill: { color: theme.secondary, transparency: 85 }
  });
  slide.addShape(pres.shapes.OVAL, {
    x: -0.5, y: 4.2, w: 2.0, h: 2.0,
    fill: { color: theme.accent, transparency: 88 }
  });

  // Title
  slide.addText("Key Takeaways", {
    x: 0.6, y: 0.3, w: 9, h: 0.65,
    fontSize: 36, fontFace: "Georgia",
    color: "FFFFFF", bold: true, align: "left",
    margin: 0
  });

  // Subtitle
  slide.addText("Prioritizing Depression, Anxiety, and Closing the Treatment Gap", {
    x: 0.6, y: 0.95, w: 9, h: 0.35,
    fontSize: 15, fontFace: "Calibri",
    color: theme.light, align: "left",
    margin: 0
  });

  // Divider line
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0.6, y: 1.4, w: 2.0, h: 0.04,
    fill: { color: theme.accent }
  });

  // Five takeaway items
  const takeaways = [
    "Depression and anxiety together represent the overwhelming majority of mental health DALYs — each generating ~690 DALYs per 100,000.",
    "Schizophrenia and bipolar carry disproportionate individual burden relative to their prevalence, requiring specialized care pathways.",
    "Treatment exists but access and quality remain inadequate — the treatment gap is a central policy challenge.",
    "Stigma suppresses both help-seeking and accurate data, meaning the true burden is likely underestimated.",
    "Policy should prioritize scaling evidence-based interventions for common mental disorders while maintaining specialized care for severe conditions."
  ];

  const startY = 1.65;
  const itemH = 0.65;

  takeaways.forEach((text, i) => {
    const iy = startY + i * itemH;

    // Number badge
    slide.addShape(pres.shapes.OVAL, {
      x: 0.6, y: iy + 0.05, w: 0.35, h: 0.35,
      fill: { color: theme.accent }
    });
    slide.addText(String(i + 1), {
      x: 0.6, y: iy + 0.05, w: 0.35, h: 0.35,
      fontSize: 14, fontFace: "Arial",
      color: "FFFFFF", bold: true,
      align: "center", valign: "middle"
    });

    // Takeaway text
    slide.addText(text, {
      x: 1.15, y: iy, w: 8.2, h: itemH,
      fontSize: 13, fontFace: "Calibri",
      color: "FFFFFF", align: "left", valign: "middle",
      lineSpacingMultiple: 1.15
    });
  });

  // Bottom source line
  slide.addText("Data: Our World in Data / IHME, Global Burden of Disease (2025)", {
    x: 0.6, y: 5.15, w: 6, h: 0.3,
    fontSize: 9, fontFace: "Calibri",
    color: theme.secondary, align: "left"
  });

  // Page number badge
  slide.addShape(pres.shapes.OVAL, {
    x: 9.3, y: 5.1, w: 0.4, h: 0.4,
    fill: { color: theme.accent }
  });
  slide.addText("8", {
    x: 9.3, y: 5.1, w: 0.4, h: 0.4,
    fontSize: 12, fontFace: "Arial",
    color: "FFFFFF", bold: true,
    align: "center", valign: "middle"
  });

  return slide;
}

if (require.main === module) {
  const pres = new pptxgen();
  pres.layout = 'LAYOUT_16x9';
  const theme = {
    primary: "006d77",
    secondary: "83c5be",
    accent: "e29578",
    light: "ffddd2",
    bg: "edf6f9"
  };
  createSlide(pres, theme);
  pres.writeFile({ fileName: "slide-08-preview.pptx" });
}

module.exports = { createSlide, slideConfig };

