const slideConfig = {
  type: 'content',
  index: 4,
  title: 'Depression and Anxiety Carry Nearly Equal Burden'
};

function createSlide(pres, theme) {
  const slide = pres.addSlide();
  slide.background = { color: theme.bg };

  // Title
  slide.addText("Depression and Anxiety Carry\nNearly Equal Disease Burden Worldwide", {
    x: 0.5, y: 0.25, w: 9, h: 0.9,
    fontSize: 28, fontFace: "Georgia",
    color: theme.primary, bold: true, align: "left",
    margin: 0, fit: "shrink"
  });

  // Left column - Depressive Disorders
