    shadow: { type: "outer", blur: 6, offset: 2, angle: 135, color: "000000", opacity: 0.1 },
    rectRadius: 0.1
  });

  // Depression bar visual (proportional height)
  const maxBarH = 2.0;
  const depVal = 694.6;
  const anxVal = 686.5;
  const maxVal = 700;
  const depBarH = (depVal / maxVal) * maxBarH;
  const anxBarH = (anxVal / maxVal) * maxBarH;

  // Depression bar
  const depBarY = 1.4 + 3.5 - 0.7 - depBarH;
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 1.5, y: depBarY, w: 1.8, h: depBarH,
    fill: { color: theme.accent },
    rectRadius: 0.05
  });

