  slide.addText("694.6", {
    x: 1.5, y: depBarY - 0.55, w: 1.8, h: 0.5,
    fontSize: 36, fontFace: "Georgia",
    color: theme.accent, bold: true, align: "center", valign: "bottom"
  });

