    x: 6.3, y: anxBarY - 0.55, w: 1.8, h: 0.5,
    fontSize: 36, fontFace: "Georgia",
    color: theme.primary, bold: true, align: "center", valign: "bottom"
  });

  // Anxiety label
  slide.addText("Anxiety\nDisorders", {
    x: 5.3, y: 3.8, w: 4.2, h: 0.55,
    fontSize: 16, fontFace: "Calibri",
    color: theme.primary, bold: true, align: "center"
  });

  // Anxiety DALY label
  slide.addText("DALYs per 100,000", {
    x: 5.3, y: 4.3, w: 4.2, h: 0.3,
    fontSize: 11, fontFace: "Calibri",
