const pptxgen = require("pptxgenjs");

const slideConfig = {
  type: 'content',
  index: 4,
  title: 'Depression and Anxiety Carry Nearly Equal Burden'
};

function createSlide(pres, theme) {
  const slide = pres.addSlide();
  slide.background = { color: theme.bg };

  // Title
  slide.addText("Depression and Anxiety Carry\nNearly Equal Disease Burden Worldwide", {
    x: 0.5, y: 0.25, w: 9, h: 0.9,
    fontSize: 28, fontFace: "Georgia",
    color: theme.primary, bold: true, align: "left",
    margin: 0, fit: "shrink"
  });

  // Left card - Depressive Disorders
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0.5, y: 1.4, w: 4.2, h: 3.3,
    fill: { color: "FFFFFF" },
    shadow: { type: "outer", blur: 6, offset: 2, angle: 135, color: "000000", opacity: 0.1 },
    rectRadius: 0.1
  });

  // Depression accent bar at top of card
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0.5, y: 1.4, w: 4.2, h: 0.07,
    fill: { color: theme.accent }
  });

  // Depression large number
  slide.addText("694.6", {
    x: 0.5, y: 1.7, w: 4.2, h: 1.2,
    fontSize: 56, fontFace: "Georgia",
    color: theme.accent, bold: true, align: "center", valign: "middle"
  });

  // Depression proportional bar (horizontal)
  const maxBarW = 3.4;
  const depBarW = (694.6 / 700) * maxBarW;
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0.5 + (4.2 - depBarW) / 2, y: 3.0, w: depBarW, h: 0.35,
    fill: { color: theme.accent, transparency: 25 },
    rectRadius: 0.05
  });

  // Depression label
  slide.addText("Depressive Disorders", {
    x: 0.5, y: 3.55, w: 4.2, h: 0.4,
    fontSize: 18, fontFace: "Calibri",
    color: theme.primary, bold: true, align: "center"
  });

  // Depression DALY label
  slide.addText("DALYs per 100,000", {
    x: 0.5, y: 3.95, w: 4.2, h: 0.3,
    fontSize: 11, fontFace: "Calibri",
    color: theme.secondary, align: "center"
  });

  // Right card - Anxiety Disorders
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 5.3, y: 1.4, w: 4.2, h: 3.3,
    fill: { color: "FFFFFF" },
    shadow: { type: "outer", blur: 6, offset: 2, angle: 135, color: "000000", opacity: 0.1 },
    rectRadius: 0.1
  });

  // Anxiety accent bar at top of card
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 5.3, y: 1.4, w: 4.2, h: 0.07,
    fill: { color: theme.primary }
  });

  // Anxiety large number
  slide.addText("686.5", {
    x: 5.3, y: 1.7, w: 4.2, h: 1.2,
    fontSize: 56, fontFace: "Georgia",
    color: theme.primary, bold: true, align: "center", valign: "middle"
  });

  // Anxiety proportional bar (horizontal)
  const anxBarW = (686.5 / 700) * maxBarW;
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 5.3 + (4.2 - anxBarW) / 2, y: 3.0, w: anxBarW, h: 0.35,
    fill: { color: theme.primary, transparency: 25 },
    rectRadius: 0.05
  });

  // Anxiety label
  slide.addText("Anxiety Disorders", {
    x: 5.3, y: 3.55, w: 4.2, h: 0.4,
    fontSize: 18, fontFace: "Calibri",
    color: theme.primary, bold: true, align: "center"
  });

  // Anxiety DALY label
  slide.addText("DALYs per 100,000", {
    x: 5.3, y: 3.95, w: 4.2, h: 0.3,
    fontSize: 11, fontFace: "Calibri",
    color: theme.secondary, align: "center"
  });

  // Center ≈ connector
  slide.addShape(pres.shapes.OVAL, {
    x: 4.55, y: 2.3, w: 0.9, h: 0.9,
    fill: { color: theme.light }
  });
  slide.addText("≈", {
    x: 4.55, y: 2.3, w: 0.9, h: 0.9,
    fontSize: 32, fontFace: "Georgia",
    color: theme.accent, bold: true, align: "center", valign: "middle"
  });

  // Bottom insight text
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0.5, y: 4.8, w: 9, h: 0.55,
    fill: { color: theme.primary, transparency: 8 },
    rectRadius: 0.08
  });
  slide.addText("Together, depression and anxiety dwarf all other mental health categories in disease burden.", {
    x: 0.7, y: 4.8, w: 8.6, h: 0.55,
    fontSize: 12, fontFace: "Calibri",
    color: theme.primary, align: "left", valign: "middle"
  });

  // Page number badge
  slide.addShape(pres.shapes.OVAL, {
    x: 9.3, y: 5.1, w: 0.4, h: 0.4,
    fill: { color: theme.accent }
  });
  slide.addText("4", {
    x: 9.3, y: 5.1, w: 0.4, h: 0.4,
    fontSize: 12, fontFace: "Arial",
    color: "FFFFFF", bold: true,
    align: "center", valign: "middle"
  });

  return slide;
}

if (require.main === module) {
  const pres = new pptxgen();
  pres.layout = 'LAYOUT_16x9';
  const theme = {
    primary: "006d77",
    secondary: "83c5be",
    accent: "e29578",
    light: "ffddd2",
    bg: "edf6f9"
  };
  createSlide(pres, theme);
  pres.writeFile({ fileName: "slide-04-preview.pptx" });
}

module.exports = { createSlide, slideConfig };

